/// 回退图标（未命中名称时）：help-circle 问号圈
const FALLBACK: &str = r#"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/></svg>"#;

/// 按名称取图标 SVG 字节；未命中时回退到 help-circle，保证不崩溃。
fn svg_for(name: &str) -> &'static [u8] {
    for (n, s) in ICONS {
        if *n == name {
            return s.as_bytes();
        }
    }
    FALLBACK.as_bytes()
}

/// 渲染一个 lucide 图标。
///
/// * `name`  —— 见 [`ICONS`] 的图标名（即 lucide 图标名）
/// * `size`  —— 显示尺寸（px，正方形）；原字形多大就传多大，保证视觉尺寸一致
/// * `color` —— 描边 / 填充色，通过 `svg::Style.color` 注入替换 `currentColor`
pub fn icon<'a>(name: &'static str, size: f32, color: Color) -> Element<'a, Message> {
    Svg::new(svg::Handle::from_memory(svg_for(name)))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
        .style(move |_t, _s| svg::Style { color: Some(color) })
        .into()
}